// 业务隔离的 login-auth 线程池（TtlExecutors 包装见 TTL 部分）
executorService = TtlExecutors.getTtlExecutorService(executorServiceFactory.getOrCreateExecutorService("login-auth"));

for (BusinessVO businessVO : request.getBusinessVOS()) {
    futures.add(CompletableFuture.supplyAsync(() -> {
        try { return new BusinessAuthorityVO(...); }             // 查角色+权限
        catch (Throwable e) { log.error(...); return null; }     // 单系统失败不影响其他系统
    }, executorService));
}
CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).get(fetchV2TimeOut, TimeUnit.SECONDS);

private static final TransmittableThreadLocal<FetchAuthorityParam> CONTEXT = new TransmittableThreadLocal<>();

initFetchAuthorityThreadContext(employeeNumber, allBusinessVOS);   // 主线程查询前初始化
try {
    ... // V2 并行 / V3 批量，子线程 CONTEXT.get() 直接拿到全量 BusinessVO
} finally {
    FetchAuthorityThreadContext.clear();   // finally 清理，防线程复用脏数据/内存泄漏
}
